import { useState } from 'react';
import styles from './TransactionForm.module.css';

const TransactionForm = ({ onAddTransaction }) => {
  const [formData, setFormData] = useState({
    description: '',
    amount: '',
    type: 'income',
  });

  // Estado para el saldo actual
  const [currentBalance, setCurrentBalance] = useState(0);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    // Validación del monto
    const amount = parseFloat(formData.amount);
    if (isNaN(amount) || amount <= 0) {
      alert('Por favor ingrese un monto válido mayor a cero');
      return;
    }

    // Preparar datos de fecha/hora
    const now = new Date();
    const transaction = {
      ...formData,
      id: Date.now(), // ID único para cada transacción
      amount: amount,
      day: now.toLocaleDateString('es-ES', { weekday: 'long' }),
      time: now.toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' }),
      date: now.toISOString().split('T')[0],
      timestamp: now.getTime() // Para ordenamiento
    };

    // Calcular nuevo saldo
    const amountToUpdate = transaction.type === 'income' ? amount : -amount;
    const newBalance = currentBalance + amountToUpdate;
    
    // Validar saldo negativo para gastos
    if (newBalance < 0 && transaction.type === 'expense') {
      alert('Saldo insuficiente para realizar esta transacción');
      return;
    }

    // Actualizar saldo
    setCurrentBalance(newBalance);
    
    // Notificar al componente padre (si es necesario)
    if (onAddTransaction) {
      onAddTransaction(transaction, newBalance);
    }
    
    // Resetear formulario
    setFormData({
      description: '',
      amount: '',
      type: 'income',
    });
  };

  return (
    <div className={styles.container}>
      <form className={styles.form} onSubmit={handleSubmit}>
        <div className={styles.balanceDisplay}>
          <h3>Saldo Actual</h3>
          <p className={currentBalance >= 0 ? styles.positiveBalance : styles.negativeBalance}>
            ${currentBalance.toFixed(2)}
          </p>
        </div>
        
        <div className={styles.formGroup}>
          <label>Descripción</label>
          <input
            type="text"
            name="description"
            placeholder="Ej: Salario, Comida, Transporte..."
            value={formData.description}
            onChange={handleChange}
            required
          />
        </div>
        
        <div className={styles.formGroup}>
          <label>Monto</label>
          <input
            type="number"
            name="amount"
            placeholder="0.00"
            value={formData.amount}
            onChange={handleChange}
            min="0.01"
            step="0.01"
            required
          />
        </div>
        
        <div className={styles.formGroup}>
          <label>Tipo</label>
          <div className={styles.radioGroup}>
            <label>
              <input
                type="radio"
                name="type"
                value="income"
                checked={formData.type === 'income'}
                onChange={handleChange}
              />
              Ingreso
            </label>
            <label>
              <input
                type="radio"
                name="type"
                value="expense"
                checked={formData.type === 'expense'}
                onChange={handleChange}
              />
              Gasto
            </label>
          </div>
        </div>
        
        <button 
          type="submit" 
          className={`${styles.submitButton} ${
            formData.type === 'income' ? styles.incomeButton : styles.expenseButton
          }`}
        >
          {formData.type === 'income' ? 'Agregar Ingreso' : 'Agregar Gasto'}
        </button>
      </form>
    </div>
  );
};

export default TransactionForm;
